pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 withdrawAmount) public {
        // Keep deposits within reasonable bounds to avoid overflow
        deposit1 = bound(deposit1, 0, 1e18);
        deposit2 = bound(deposit2, 0, 1e18);
        // withdrawAmount must not exceed deposit1 (sender's credit after first deposit)
        withdrawAmount = bound(withdrawAmount, 0, deposit1);
        vm.assume(deposit1 > 0);

        address alice = address(0x1);
        address bob = address(0x2);

        // Alice deposits
        vm.deal(alice, deposit1);
        vm.prank(alice);
        c.deposit{value: deposit1}();

        // Bob deposits
        vm.deal(bob, deposit2);
        vm.prank(bob);
        c.deposit{value: deposit2}();

        // Alice withdraws part of her credit
        vm.prank(alice);
        c.withdrawAll();

        // Assert: contract internal balance should never exceed total deposited - total withdrawn
        // In reference: balance = (deposit1 + deposit2) - withdrawAmount
        // In mutant:    balance = (deposit1 + deposit2) + withdrawAmount
        // The invariant: balance <= address(c).balance (since address(c).balance holds real ETH)
        assertTrue(c.balance() <= address(c).balance);
    }
}

