pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawalAmount) public {
        // Keep amounts reasonable to avoid overflow
        depositAmount = bound(depositAmount, 1, 1e18);
        withdrawalAmount = bound(withdrawalAmount, 1, 1e18);

        // An EOA can call, but a low-level call to an EOA always succeeds.
        // To model a failing counterparty, we must deploy an adversarial helper.
        Reverter badCallee = new Reverter();

        // Setup: Fund ourselves and deposit
        vm.deal(address(this), depositAmount);
        c.deposit{value: depositAmount}();

        // We want a withdrawal that fails at the call level (badCallee reverts).
        // The mutant increases balance, the correct one decreases it.
        // Since the call reverts, no Ether is actually sent, but the state change to balance persists in both.
        // Setup credit for the bad callee
        vm.deal(address(this), withdrawalAmount);
        vm.prank(address(badCallee));
        c.deposit{value: withdrawalAmount}();

        // Now badCallee has credit = withdrawalAmount, balance = depositAmount + withdrawalAmount
        // badCallee calls withdrawAll, which will attempt to send Ether to itself and revert.
        // The correct contract: balance -= withdrawalAmount
        // The mutant contract: balance += withdrawalAmount
        // After the revert, state changes to balance and credit are rolled back,
        // EXCEPT in the case where we use .call which respects revert, but the state
        // changes before the call are not rolled back if the entire transaction reverts.
        // Actually, in Solidity, if require(callResult) fails, the whole transaction reverts,
        // so the state change to balance is reverted too. We need a different approach:
        // We must observe the balance variable without the call reverting.

        // Let's use a re-entrant attacker that succeeds partially?
        // No, the rule: after a successful withdrawal where call succeeds, the sum
        // balance + address(c).balance should remain constant?

        // Let's use a helper that accepts Ether but whose fallback does something
        // that causes a discrepancy. The simplest: a normal EOA works, but we need
        // the fuzzer to find any input. The bug is that balance is increased on withdrawal.
        // So if a withdrawal succeeds (call succeeds), the correct contract decreases balance,
        // the mutant increases balance. After the withdrawal, the correct contract's
        // address(c).balance has decreased by the amount, and balance has decreased by the amount.
        // The mutant's address(c).balance has decreased, but balance has increased.
        // So address(c).balance + balance changes in the mutant, but stays the same in the correct.
        // That doesn't require an adversarial callee; a regular EOA works.
        // But the fuzzed address is an EOA, call succeeds, so we can just use the fuzzed actor.
        // The earlier failed approaches tried exactly that but had compilation errors.

        // We need a property that holds for the correct contract and fails for the mutant.
        // Let's use the invariant: balance == totalDeposited - totalWithdrawn.
        // We can track that with a shadow variable or by using address(this).balance.
        // But we don't have a getter for totalDeposited. We can compute it from deposits we made.

        // Simpler: After a deposit and a successful withdrawal, the balance variable
        // should be less than or equal to address(c).balance in the correct contract
        // (because balance tracks Ether actually held, but it might be less due to
        // direct sends? Actually, only deposit and withdraw affect balance, and they
        // keep it equal to address(c).balance in correct contract). In mutant,
        // balance becomes larger than address(c).balance.

        // Let's use: balance <= address(c).balance for correct contract.
        // After a deposit, they are equal. After a successful withdrawal, they remain equal.
        // In mutant, after withdrawal, balance > address(c).balance.
        // So the property "balance() <= address(c).balance" holds for correct and fails for mutant.

        // We need to call withdrawAll from an EOA that has credit.
        // Let's use a fresh address as the depositor/withdrawer.
        address actor = address(1234); // fuzzed? We can fuzz the actor too.
        // But the fuzzer provides parameters. We'll take an address parameter.
    }
}

contract Reverter {
    fallback() external payable {
        revert("fail");
    }
}

