pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address fuzzedActor;
    uint256 fuzzedAmount;
    uint256 fuzzedSeed;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, uint256 amount, uint256 seed) public {
        // Restrict actor to a non-zero address to avoid precompile issues
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));

        // Restrict amount to a reasonable range to avoid overflow and ensure sufficient funds
        amount = bound(amount, 1, 1_000_000 ether);

        // Provide actor with enough ETH for deposit
        vm.deal(actor, amount * 2);

        // First deposit
        vm.prank(actor);
        c.deposit{value: amount}();

        // Perform withdrawAll (actor has credit)
        uint256 balanceBefore = actor.balance;
        vm.prank(actor);
        c.withdrawAll();
        uint256 withdrawn = actor.balance - balanceBefore;

        // Now balance should be 1 (due to bug) or 0 (correct)
        // Perform another withdrawAll when actor has 0 credit
        // This will still trigger `balance += 1` in buggy version without any withdrawal
        vm.prank(actor);
        c.withdrawAll();

        // Record deposits: only one deposit of `amount` occurred
        // Record withdrawals: only one successful withdrawal of `withdrawn` occurred
        // Expected balance = deposits - withdrawals = amount - withdrawn (should be 0 in reference)
        // Bug adds 1 for each withdrawAll call: 2 calls -> +2
        // So actual balance must equal expected balance
        uint256 actualBalance = c.balance();
        uint256 expectedBalance = amount - withdrawn;
        assertTrue(actualBalance == expectedBalance);
    }
}

