pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint8 calls) public {
        // Keep amounts in admissible range (non-zero deposits may be made)
        vm.assume(amount1 > 0 && amount1 < 1 ether);
        vm.assume(amount2 > 0 && amount2 < 1 ether);
        vm.assume(calls > 0 && calls <= 10);

        // Use two separate actors to deposit, so credit exists
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, amount1);
        vm.prank(alice);
        c.deposit{value: amount1}();
        vm.deal(bob, amount2);
        vm.prank(bob);
        c.deposit{value: amount2}();

        // Record total deposits
        uint256 totalDeposits = amount1 + amount2;

        // Make `calls` calls to withdrawAll from both actors alternating
        for (uint8 i = 0; i < calls; i++) {
            if (i % 2 == 0) {
                vm.prank(alice);
            } else {
                vm.prank(bob);
            }
            c.withdrawAll();
        }

        // After all calls, compute total remaining credit
        uint256 creditAlice = c.credit(alice);
        uint256 creditBob = c.credit(bob);
        uint256 expectedBalance = totalDeposits - creditAlice - creditBob;

        // The invariant: balance = totalDeposits - totalCredit
        // The bug adds 1 per call, so balance will be higher than expected.
        assertEq(address(c).balance, expectedBalance, "invariant: balance == deposits - credit");
    }
}

