import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmt, uint8 times, uint8 withdrawalCount) public {
        // Admissible domain: deposit amount bounded to avoid overflow in total deposits, times >= 1
        vm.assume(times >= 1);
        vm.assume(depositAmt <= type(uint128).max / times);
        // withdrawalCount can be any uint8; we will use it mod (times+1) to get a number of withdrawAll calls

        // Pick a single actor
        address actor = address(0x1234);
        vm.deal(actor, depositAmt * times);

        // Perform deposits
        uint totalDeposits = 0;
        for (uint i = 0; i < times; i++) {
            vm.prank(actor);
            c.deposit{value: depositAmt}();
            totalDeposits += depositAmt;
        }

        // Track total successfully withdrawn (only what's actually sent out)
        uint totalWithdrawn = 0;
        // Perform a number of withdrawAll calls (fuzzed through withdrawalCount)
        uint calls = withdrawalCount % (times + 1); // 0 to times inclusive
        for (uint i = 0; i < calls; i++) {
            uint balBefore = address(c).balance;
            uint actorCredit = c.credit(actor); // public getter exists?
            // credit is mapping, no getter. We can compute expected withdrawal from prior state.
            // We'll instead capture contract balance before the call, and after, diff is withdrawn amount.

            vm.prank(actor);
            try c.withdrawAll() {
                uint balAfter = address(c).balance;
                // If successful, the contract paid out balBefore - balAfter.
                totalWithdrawn += balBefore - balAfter;
            } catch {
                // No withdrawal happened, ignore
            }
        }

        // Invariant: contract balance <= totalDeposits - totalWithdrawn
        // Bug adds 1 to balance on every withdrawAll call, so balance > totalDeposits - totalWithdrawn after any call.
        assertTrue(address(c).balance <= totalDeposits - totalWithdrawn);
    }
}

